1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "membershipLevel",
27	        expression = "java(Math.min(3, 1 "
28	            + "+ (owner.getEmail() != null && !owner.getEmail().isEmpty() ? 1 : 0) "
29	            + "+ (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)))")
30	    @Mapping(target = "locality", expression = "java(deriveLocality(owner))")
31	    @Mapping(target = "ageBand", expression = "java(deriveAgeBand(owner))")
32	    @Mapping(target = "checkDigit", expression = "java(luhnCheckDigit(owner.getCustomerCode()))")
33	    @Mapping(target = "contactPreference",
34	        expression = "java(owner.getEmail() != null && !owner.getEmail().isEmpty() "
35	            + "? org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.EMAIL "
36	            + ": org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.PHONE)")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
42	    @Mapping(target = "pets", ignore = true)
43	    Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
46	
47	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
48	
49	    /**
50	     * Derive the locality region for an owner from its region-and-hash customer code. The customer code
51	     * is {@code <REGION>-<HASH8>}, so the locality is the region segment before the first hyphen (the
52	     * same region the identity itself was built from: postcode range first, then the city-to-region
53	     * table, otherwise "UNKNOWN"). When no customer code is present, the locality is "UNKNOWN".
54	     */
55	    default String deriveLocality(Owner owner) {
56	        String customerCode = owner.getCustomerCode();
57	        if (customerCode != null) {
58	            int dash = customerCode.indexOf('-');
59	            if (dash > 0) {
60	                return customerCode.substring(0, dash);
61	            }
62	        }
63	        return "UNKNOWN";
64	    }
65	
66	    /**
67	     * Derive the owner's age band from its birth date, computed against the registration date. The age
68	     * is the number of whole years between the birth date and the effective registration date (falling
69	     * back to the current date when no registration date is present): {@code MINOR} when under 18,
70	     * {@code ADULT} for 18-64 and {@code SENIOR} for 65 and over. Returns {@code null} when no birth
71	     * date was supplied, so the field is absent from the response.
72	     */
73	    default OwnerDto.AgeBandEnum deriveAgeBand(Owner owner) {
74	        java.time.LocalDate birthDate = owner.getBirthDate();
75	        if (birthDate == null) {
76	            return null;
77	        }
78	        java.time.LocalDate reference = owner.getRegistrationDate() != null
79	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
80	        int age = java.time.Period.between(birthDate, reference).getYears();
81	        if (age < 18) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (age < 65) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
89	
90	    /**
91	     * Compute the single Luhn check digit (0-9) over the digits contained in the given value.
92	     * Non-digit characters (such as the hyphens in a customer code) are ignored. A null or
93	     * digit-free value yields a check digit of 0.
94	     */
95	    default Integer luhnCheckDigit(String value) {
96	        if (value == null) {
97	            return 0;
98	        }
99	        int sum = 0;
100	        boolean doubleDigit = true;
101	        for (int i = value.length() - 1; i >= 0; i--) {
102	            char c = value.charAt(i);
103	            if (c < '0' || c > '9') {
104	                continue;
105	            }
106	            int digit = c - '0';
